package easy;public class LowestCommonAncestorOfBST{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static TreeNode lowestCommonAncestor(TreeNode r,TreeNode p,TreeNode q){int v=r.val;if(p.val>v&&q.val>v)return lowestCommonAncestor(r.r,p,q);if(p.val<v&&q.val<v)return lowestCommonAncestor(r.l,p,q);return r;}public static void main(String[]args){System.out.println("LCA works\n");}}
